const std::map<juce::String, const char*>& table (Language l)
{
    switch (l)
    {
        case Italian: return it();
        case Spanish: return es();
        case French: return fr();
        case German: return de();
        case Portuguese: return pt();
        default: break;
    }
    static const std::map<juce::String, const char*> empty;
    return empty;
}
